function countVowels(word) {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  const n = word.length;
  let total = 0;
  for (let i = 0; i < n; i++) {
    if (vowels.has(word[i])) {
      total += (i + 1) * (n - i);
    }
  }
  return total;
}

brute:
function countVowels(word) {
  const isVowel = ch => 'aeiou'.includes(ch);
  let sum = 0;
  // Grow each substring one character at a time, keeping its vowel count.
  for (let start = 0; start < word.length; start++) {
    let inside = 0;
    for (let end = start; end < word.length; end++) {
      if (isVowel(word[end])) inside++;
      sum += inside;
    }
  }
  return sum;
}

