function generate(rand, size) {
  const alphabets = ['abcdefghijklmnopqrstuvwxyz', 'aeiou', 'bcdfg', 'ab', 'xyzu'];
  const letters = alphabets[Math.floor(rand() * alphabets.length)];
  const n = size === 'large' ? 8000 + Math.floor(rand() * 2001) : 1 + Math.floor(rand() * 20);
  let word = '';
  for (let i = 0; i < n; i++) word += letters[Math.floor(rand() * letters.length)];
  return [word];
}
